63	func decode(t *testing.T, resp *http.Response) (int, map[string]any) {
64		t.Helper()
65		raw, err := io.ReadAll(resp.Body)
66		if err != nil {
67			t.Fatalf("read body: %v", err)
68		}
69		var out map[string]any
70		if err := json.Unmarshal(raw, &out); err != nil {
71			t.Fatalf("decode %q: %v", raw, err)
72		}
