94	func TestPostCreatesReplaysAndPersists(t *testing.T) {
95		server, store, _ := newTestServer(t)
96		body := `{"events":[
97			{"id":"e1","service":"gateway","severity":" CRITICAL ","message":" spike ","at":"2026-10-01T10:00:00.123456789+08:00"},
98			{"id":"e2","service":"api","severity":"info","message":"ok","at":"2026-10-01T09:00:00Z"}
99		]}`
100		status, out := post(t, server, body)
101		if status != http.StatusOK {
102			t.Fatalf("status=%d body=%v", status, out)
103		}
104		if out["created"].(float64) != 2 || out["replayed"].(float64) != 0 {
105			t.Fatalf("unexpected counts: %v", out)
106		}
107		if len(store.appended) != 1 || store.appended[0] != 2 {
108			t.Fatalf("expected one durable batch of 2, got %v", store.appended)
109		}
110	
111		// Identical retry (same instant expressed in UTC) is fully replayed.
112		retry := `{"events":[{"id":"e1","service":"gateway","severity":"critical","message":"spike","at":"2026-10-01T02:00:00.123456789Z"}]}`
113		status, out = post(t, server, retry)
114		if status != http.StatusOK {
115			t.Fatalf("retry status=%d body=%v", status, out)
116		}
117		if out["created"].(float64) != 0 || out["replayed"].(float64) != 1 {
118			t.Fatalf("retry counts: %v", out)
119		}
120		if len(store.appended) != 1 {
121			t.Fatal("replay must not touch storage")
122		}
123	
124		status, rows := get(t, server, "")
125		arr := rows.([]any)
126		if status != http.StatusOK || len(arr) != 2 {
127			t.Fatalf("get: status=%d rows=%v", status, arr)
128		}
129		// e1 is 10:00+08 == 02:00 UTC, so it precedes e2 at 09:00 UTC.
130		first := arr[0].(map[string]any)
131		if first["id"] != "e1" || first["severity"] != "critical" || first["message"] != "spike" {
132			t.Fatalf("ordering/normalization wrong: %v", first)
133		}
134		if got := arr[1].(map[string]any)["at"]; got != "2026-10-01T09:00:00Z" {
135			t.Fatalf("second row timestamp: %v", got)
136		}
137	}
138	
139	func TestPostRejectsBadInput(t *testing.T) {
140		server, store, _ := newTestServer(t)
141		cases := map[string]string{
142			"not json":            `{not json`,
143			"missing events":      `{}`,
144			"events not array":    `{"events":{}}`,
