239		}
240		arr, ok := out.([]any)
241		if !ok || len(arr) != 0 {
242			t.Fatalf("empty result must be [], got %v", out)
243		}
244	
245		for _, q := range []string{
246			"?since=2026-10-01T10:00:00Z&until=2026-10-01T09:00:00Z",
247			"?since=banana",
248			"?until=2026-13-99T00:00:00Z",
249		} {
250			resp, err := http.Get(server.URL + "/events" + q)
251			if err != nil {
252				t.Fatal(err)
253			}
254			raw, _ := io.ReadAll(resp.Body)
255			resp.Body.Close()
256			var errBody map[string]any
257			_ = json.Unmarshal(raw, &errBody)
258			if resp.StatusCode != http.StatusBadRequest {
