260			}
261			if msg, _ := errBody["error"].(string); msg == "" {
262				t.Fatalf("%s missing error string", q)
263			}
264		}
265	}
266	
267	func TestUnknownRouteAndMethod(t *testing.T) {
268		server, _, _ := newTestServer(t)
269		resp, err := http.Get(server.URL + "/nope")
270		if err != nil {
271			t.Fatal(err)
272		}
273		defer resp.Body.Close()
274		if resp.StatusCode != http.StatusNotFound {
