193	func TestIngestConcurrentSameContent(t *testing.T) {
194		tl := NewTimeline()
195		at := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
196		var commits int64
197		commit := func(created []Event) error {
198			atomic.AddInt64(&commits, 1)
199			return nil
200		}
201	
202		const n = 64
203		start := make(chan struct{})
204		var wg sync.WaitGroup
205		var created, replayed, failures int64
206		for range n {
207			wg.Add(1)
208			go func() {
