package httpapi

import (
	"errors"
	"net/http"
	"strconv"
	"time"

	"github.com/cocosolocoder/signalroom/internal/events"
)

// maxStepSeconds and minStepSeconds bound the required step parameter.
const (
	minStepSeconds = 1
	maxStepSeconds = 86400
)

type compareResponse struct {
	BaselineTotal int                 `json:"baseline_total"`
	ObservedTotal int                 `json:"observed_total"`
	Difference    int                 `json:"difference"`
	Ratio         *float64            `json:"ratio"`
	Segments      []compareSegmentDTO `json:"segments"`
}

type compareSegmentDTO struct {
	BaselineSince string `json:"baseline_since"`
	BaselineUntil string `json:"baseline_until"`
	Since         string `json:"since"`
	Until         string `json:"until"`
	BaselineCount int    `json:"baseline_count"`
	ObservedCount int    `json:"observed_count"`
	Difference    int    `json:"difference"`
}

func (h *Handler) compareEvents(w http.ResponseWriter, r *http.Request) {
	if h.unavailable() {
		writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
		return
	}
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", "GET")
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
		return
	}

	values := r.URL.Query()
	baselineSince, ok := singleValue(values, "baseline_since")
	if !ok {
		writeError(w, http.StatusBadRequest, "baseline_since is required exactly once as an RFC3339Nano timestamp")
		return
	}
	baselineUntil, ok := singleValue(values, "baseline_until")
	if !ok {
		writeError(w, http.StatusBadRequest, "baseline_until is required exactly once as an RFC3339Nano timestamp")
		return
	}
	since, ok := singleValue(values, "since")
	if !ok {
		writeError(w, http.StatusBadRequest, "since is required exactly once as an RFC3339Nano timestamp")
		return
	}
	until, ok := singleValue(values, "until")
	if !ok {
		writeError(w, http.StatusBadRequest, "until is required exactly once as an RFC3339Nano timestamp")
		return
	}
	rawStep, ok := singleValue(values, "step")
	if !ok || !isDecimal(rawStep) {
		writeError(w, http.StatusBadRequest, "step is required exactly once as a decimal integer number of seconds")
		return
	}
	stepSeconds, err := strconv.ParseInt(rawStep, 10, 64)
	if err != nil || stepSeconds < minStepSeconds || stepSeconds > maxStepSeconds {
		writeError(w, http.StatusBadRequest, "step must be a decimal integer between 1 and 86400 seconds")
		return
	}

	parseTime := func(value, name string) (time.Time, bool) {
		parsed, perr := time.Parse(time.RFC3339Nano, value)
		if perr != nil {
			writeError(w, http.StatusBadRequest, name+" must be an RFC3339Nano timestamp")
			return time.Time{}, false
		}
		return parsed, true
	}
	baselineStart, ok := parseTime(baselineSince, "baseline_since")
	if !ok {
		return
	}
	baselineEnd, ok := parseTime(baselineUntil, "baseline_until")
	if !ok {
		return
	}
	observedStart, ok := parseTime(since, "since")
	if !ok {
		return
	}
	observedEnd, ok := parseTime(until, "until")
	if !ok {
		return
	}

	query := events.CompareQuery{
		Service:       values.Get("service"),
		Severity:      values.Get("severity"),
		BaselineSince: baselineStart,
		BaselineUntil: baselineEnd,
		Since:         observedStart,
		Until:         observedEnd,
		Step:          time.Duration(stepSeconds) * time.Second,
	}
	result, err := h.timeline.Compare(query)
	if err != nil {
		if errors.Is(err, events.ErrCompareParams) {
			writeError(w, http.StatusBadRequest, "both windows must start before they end, have equal lengths, and span at most 10000 segments")
			return
		}
		writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
		return
	}

	segments := make([]compareSegmentDTO, len(result.Segments))
	for i, segment := range result.Segments {
		segments[i] = compareSegmentDTO{
			BaselineSince: utcRFC3339Nano(segment.BaselineStart),
			BaselineUntil: utcRFC3339Nano(segment.BaselineEnd),
			Since:         utcRFC3339Nano(segment.Start),
			Until:         utcRFC3339Nano(segment.End),
			BaselineCount: segment.BaselineCount,
			ObservedCount: segment.Count,
			Difference:    segment.Count - segment.BaselineCount,
		}
	}
	writeJSON(w, http.StatusOK, compareResponse{
		BaselineTotal: result.BaselineTotal,
		ObservedTotal: result.ObservedTotal,
		Difference:    result.Difference,
		Ratio:         result.Ratio,
		Segments:      segments,
	})
}

// singleValue returns a parameter only when it appears exactly once. A missing
// key and a repeated key are indistinguishable to callers (both are invalid)
// but distinct internally via the boolean.
func singleValue(values map[string][]string, name string) (string, bool) {
	vs, present := values[name]
	if !present || len(vs) != 1 {
		return "", false
	}
	return vs[0], true
}

// isDecimal accepts a non-empty run of ASCII digits, rejecting signs, spaces,
// fractions, and other notation that ParseInt might otherwise tolerate.
func isDecimal(value string) bool {
	if value == "" {
		return false
	}
	for _, r := range value {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

func utcRFC3339Nano(t time.Time) string {
	return t.UTC().Format(time.RFC3339Nano)
}

