	BaselineCount int
	Count         int
}

// CompareResult holds the aggregate change between two windows plus every
// aligned segment. Ratio is the relative change (observation minus baseline
// over baseline); it is nil when the baseline total is zero.
type CompareResult struct {
	BaselineTotal  int
	ObservedTotal  int
	Difference     int
	Ratio          *float64
	Segments       []CompareSegment
}

// ErrCompareParams reports an invalid compare request: a non-positive step,
// a window whose start is not strictly before its end, unequal window lengths,
// or more than maxCompareSegments segments per side. The HTTP layer is
// additionally responsible for bounding the step to its accepted range.
var ErrCompareParams = errors.New("invalid compare parameters")

// Compare validates the windows and counts filtered events inside them using
// a single read of the timeline, so both sides, both totals, and every segment
// reflect one committed snapshot: a batch committed during the call is either
// fully present or fully absent.
func (t *Timeline) Compare(query CompareQuery) (CompareResult, error) {
	segments, err := ValidateCompareWindows(query)
	if err != nil {
		return CompareResult{}, err
	}

	service := strings.TrimSpace(query.Service)
	severity := strings.ToLower(strings.TrimSpace(query.Severity))

	baselineCounts := make([]int, len(segments))
	observedCounts := make([]int, len(segments))

	t.mu.RLock()
	for _, event := range t.events {
		if service != "" && event.Service != service {
			continue
		}
		if severity != "" && event.Severity != severity {
			continue
		}
		if i, ok := bucketIndex(event.At, query.BaselineSince, query.BaselineUntil, query.Step); ok {
			baselineCounts[i]++
		}
		if i, ok := bucketIndex(event.At, query.Since, query.Until, query.Step); ok {
			observedCounts[i]++
		}
	}
	t.mu.RUnlock()

	for i := range segments {
		segments[i].BaselineCount = baselineCounts[i]
		segments[i].Count = observedCounts[i]
	}

	result := CompareResult{Segments: segments}
	for i := range segments {
		result.BaselineTotal += baselineCounts[i]
		result.ObservedTotal += observedCounts[i]
	}
	result.Difference = result.ObservedTotal - result.BaselineTotal
	if result.BaselineTotal != 0 {
		ratio := float64(result.Difference) / float64(result.BaselineTotal)
		result.Ratio = &ratio
	}
	return result, nil
}

// ValidateCompareWindows enforces a positive step, strictly increasing and
// equal-length windows, and the per-side segment limit, then returns the
// aligned segment skeleton. Windows may overlap and are compared by absolute
// instant, so time zones are irrelevant.
func ValidateCompareWindows(query CompareQuery) ([]CompareSegment, error) {
	if query.Step <= 0 {
		return nil, ErrCompareParams
	}
	baselineLen := query.BaselineUntil.Sub(query.BaselineSince)
	observedLen := query.Until.Sub(query.Since)
	if baselineLen <= 0 || observedLen <= 0 || baselineLen != observedLen {
		return nil, ErrCompareParams
	}
	// Count in ceiling-division form without an addition that could overflow
	// for windows close to the maximum representable duration.
	count := baselineLen / query.Step
	if baselineLen%query.Step != 0 {
		count++
	}
	if count > maxCompareSegments {
		return nil, ErrCompareParams
	}
	segments := int(count)

	out := make([]CompareSegment, segments)
	for i := range out {
		baselineStart := query.BaselineSince.Add(query.Step * time.Duration(i))
		observedStart := query.Since.Add(query.Step * time.Duration(i))
		baselineEnd := baselineStart.Add(query.Step)
		if baselineEnd.After(query.BaselineUntil) {
			baselineEnd = query.BaselineUntil
		}
		observedEnd := observedStart.Add(query.Step)
		if observedEnd.After(query.Until) {
			observedEnd = query.Until
		}
		out[i] = CompareSegment{
			BaselineStart: baselineStart,
			BaselineEnd:   baselineEnd,
			Start:         observedStart,
			End:           observedEnd,
		}
	}
	return out, nil
}

// bucketIndex reports the zero-based segment, measured in whole steps from the
// window start, that contains at. The window is half-open: [start, end).
// Segment boundaries aligned exactly with a start are counted in that
// segment; an instant equal to the window end is excluded.
func bucketIndex(at, start, end time.Time, step time.Duration) (int, bool) {
	if at.Before(start) || !at.Before(end) {
		return 0, false
	}
	offset := at.Sub(start)
	if offset < 0 {
		return 0, false
	}
	return int(offset / step), true
}

