8	
9	func TestValidateCompareWindowsSegments(t *testing.T) {
10		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
11		query := CompareQuery{
12			BaselineSince: base,
13			BaselineUntil: base.Add(10 * time.Minute),
14			Since:         base.Add(time.Hour),
15			Until:         base.Add(time.Hour + 10*time.Minute),
16			Step:          4 * time.Minute,
17		}
18		segments, err := ValidateCompareWindows(query)
19		if err != nil {
20			t.Fatalf("validate: %v", err)
21		}
22		if len(segments) != 3 {
23			t.Fatalf("ten minutes at four minutes must yield three segments, got %d", len(segments))
24		}
25		wantLengths := []time.Duration{4 * time.Minute, 4 * time.Minute, 2 * time.Minute}
26		for i, want := range wantLengths {
27			if got := segments[i].BaselineEnd.Sub(segments[i].BaselineStart); got != want {
28				t.Fatalf("baseline segment %d length = %v, want %v", i, got, want)
29			}
30			if got := segments[i].End.Sub(segments[i].Start); got != want {
31				t.Fatalf("observed segment %d length = %v, want %v", i, got, want)
32			}
33		}
34		if !segments[0].BaselineStart.Equal(base) || !segments[2].BaselineEnd.Equal(base.Add(10*time.Minute)) {
35			t.Fatalf("segments must cover the full window exactly: %+v", segments)
36		}
37		if !segments[0].Start.Equal(base.Add(time.Hour)) || !segments[2].End.Equal(base.Add(time.Hour+10*time.Minute)) {
38			t.Fatalf("observed window boundary mismatch: %+v", segments)
39		}
40		// Adjacent segments meet without gaps or overlaps.
41		for i := 1; i < len(segments); i++ {
42			if !segments[i].BaselineStart.Equal(segments[i-1].BaselineEnd) {
43				t.Fatalf("baseline segments not contiguous at %d", i)
44			}
45			if !segments[i].Start.Equal(segments[i-1].End) {
46				t.Fatalf("observed segments not contiguous at %d", i)
47			}
48		}
49	}
50	
51	func TestValidateCompareWindowsRejects(t *testing.T) {
52		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
