55			"zero step": {
56				BaselineSince: base, BaselineUntil: tenMin,
57				Since: base.Add(time.Hour), Until: base.Add(time.Hour + 10*time.Minute),
58			},
59			"negative step": {
60				BaselineSince: base, BaselineUntil: tenMin,
61				Since: base.Add(time.Hour), Until: base.Add(time.Hour + 10*time.Minute),
62				Step: -time.Second,
63			},
64			"baseline inverted": {
65				BaselineSince: tenMin, BaselineUntil: base,
66				Since: base.Add(time.Hour), Until: base.Add(time.Hour + 10*time.Minute),
